// Design prototype only. All records below are synthetic and stay in this page's memory.
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const icon=name=>`<svg aria-hidden="true"><use href="#${name}"/></svg>`;
const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ar=n=>new Intl.NumberFormat('ar-EG',{useGrouping:false}).format(n);
const grades=['','الأول المتوسط','الثاني المتوسط','الثالث المتوسط'];
const subjects=[{id:1,name:'الرياضيات',quota:5},{id:2,name:'اللغة العربية',quota:5},{id:3,name:'اللغة الإنجليزية',quota:4},{id:4,name:'العلوم',quota:4},{id:5,name:'مهارات حياتية',quota:1},{id:6,name:'تفكير ناقد',quota:1},{id:7,name:'النشاط',quota:1}];
const names=['أحمد عبدالله','خالد محمد','عمر إبراهيم','عبدالله ناصر','يوسف سالم','محمد علي','حسن أحمد','إبراهيم فهد','ناصر سعيد','فهد عبدالله','صالح عمر','علي حسن','سالم محمود','بدر خالد','طارق إبراهيم','سعد محمد','ماجد ناصر','راشد علي','عادل حسن','وليد فهد','زياد أحمد','هشام سالم','حسام خالد','أسامة عمر'];
const teachers=names.map((name,i)=>({id:i+1,name,specialty:subjects[Math.floor(i/6)].name,subjectId:Math.floor(i/6)+1,max:24}));
let classrooms=Array.from({length:12},(_,i)=>({id:i+1,grade:Math.floor(i/4)+1,section:i%4+1}));
let requirements=classrooms.flatMap(c=>subjects.map(s=>({id:`${c.id}-${s.id}`,classId:c.id,subjectId:s.id,quota:s.quota,pairs:s.id===1?1:0})));
const assignments=new Map();
requirements.forEach((r,i)=>{if(i%9===0||i%17===0)return;const c=classrooms.find(x=>x.id===r.classId);const tid=r.subjectId<=4?(r.subjectId-1)*6+(c.id-1)%6+1:(c.id+r.subjectId)%24+1;assignments.set(r.id,{mode:'SingleTeacher',members:[{id:tid,count:r.quota,pairs:r.pairs}]});});
let baseline=structuredClone(assignments),view='assignments',grade=0,search='',pendingOnly=false,teacherView=false,page=1,selectedClasses=new Set([1,2,5]),editing=null,editMembers=[],editMode='SingleTeacher',pickerSearch='',focusOrigin=null;
const changed=()=>requirements.filter(r=>JSON.stringify(assignments.get(r.id))!==JSON.stringify(baseline.get(r.id))).length;
const code=c=>`${c.grade}/${c.section}`;
const classLabel=c=>`${grades[c.grade]} · شعبة ${ar(c.section)}`;
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,3500);}
function openDialog(id){focusOrigin=document.activeElement;$(id).showModal();}
function closeDialog(id){$(id).close();focusOrigin?.focus();}
function load(tid,override=null){let total=0;for(const r of requirements){const a=override&&r.id===editing?.id?override:assignments.get(r.id);total+=a?.members.find(m=>m.id===tid)?.count||0;}return total;}
function draftBar(){return changed()?`<div class="draft-bar"><div><span class="draft-indicator"></span><div><strong>${ar(changed())} إسنادات معدّلة</strong><small>التعديلات لم تُحفظ داخل النموذج بعد.</small></div></div><div><button data-action="discard">تجاهل</button><button class="primary" data-action="save">${icon('check')}حفظ التغييرات</button></div></div>`:'';}
function gradeButtons(){return `<div class="grade-tabs" aria-label="تصفية حسب الصف">${[0,1,2,3].map(g=>`<button data-grade="${g}" aria-pressed="${grade===g}">${g?grades[g].replace(' المتوسط',''):'كل الصفوف'}</button>`).join('')}</div>`;}
function render(){
 $$('[data-view]').forEach(b=>b.setAttribute('aria-current',b.dataset.view===view?'page':'false'));
 const titles={assignments:['إسنادات التدريس','وزّع مواد الفصول، وراجع نصاب كل معلم قبل حفظ التغييرات.','إسنادات التدريس'],catalog:['بداية واضحة لكل فصل.','أنشئ شعب الصف مرة واحدة، لتظهر بنفس الاسم في جميع اختيارات المدرسة.','سجل الفصول'],teacher:['اختر فصولك، بدون كتابة.','الفصول متاحة من سجل المدرسة. اختر أكثر من فصل ثم احفظ اختيارك مباشرة.','فصول المعلم']};
 [$('#page-title').textContent,$('#page-description').textContent,$('#breadcrumb-current').textContent]=titles[view];
 $('#workspace').innerHTML=view==='assignments'?assignmentMarkup():view==='catalog'?catalogMarkup():teacherMarkup();
}
function assignmentMarkup(){const done=[...assignments.values()].filter(x=>x.members.length).length,total=requirements.length;
 return `<section class="surface"><header class="ledger-heading"><div><h2>${teacherView?'نصاب المعلمين':'مصفوفة الفصول والمواد'}</h2><p>${teacherView?'كل الإسنادات محسوبة، حتى خارج الفلاتر.':'افتح أي خلية لإسناد معلم أو لتعديل توزيع الحصص.'}</p></div><div class="view-switch" aria-label="طريقة عرض الإسنادات"><button data-action="matrix" aria-pressed="${!teacherView}">${icon('grid')}الفصول والمواد</button><button data-action="teachers" aria-pressed="${teacherView}">${icon('users')}المعلمون</button></div></header><div class="summary-line"><span><b>${ar(classrooms.length)}</b>فصل دراسي</span><span><b>${ar(done)}</b>إسناد مكتمل</span><span class="pending-count"><b>${ar(total-done)}</b>بانتظار الإسناد</span><div class="progress"><span>${ar(Math.round(done/total*100))}٪ مكتمل</span><div class="progress-track"><div class="progress-fill" style="width:${done/total*100}%"></div></div></div></div>${teacherView?teacherTable():matrixMarkup()}<footer class="ledger-footer"><span>${teacherView?'النصاب يشمل جميع المواد، مع احتساب التدريس المشترك وتقسيم الحصص.':'الفصول من سجل المدرسة · المواد من متطلبات الجدول'}</span><div class="legend"><span><i></i>تعديل غير محفوظ</span><span><i></i>إسناد محفوظ</span></div></footer></section>${draftBar()}`;
}
function matrixMarkup(){let rows=classrooms.filter(c=>(!grade||c.grade===grade)&&requirements.some(r=>r.classId===c.id&&matches(r)));
 return `<div class="filters">${gradeButtons()}<div class="filters-left"><label class="search-field">${icon('search')}<input id="matrix-search" type="search" value="${esc(search)}" placeholder="معلم، مادة أو فصل" aria-label="البحث في الإسنادات"></label><label><input id="pending-filter" type="checkbox" ${pendingOnly?'checked':''}>غير المسند فقط</label></div></div><div class="matrix-scroll" tabindex="0" aria-label="جدول الفصول والمواد قابل للتمرير"><table class="matrix"><caption hidden>مصفوفة الإسنادات التجريبية</caption><thead><tr><th scope="col">الفصل / المادة</th>${subjects.map(s=>`<th scope="col">${s.name}<small>${ar(s.quota)} حصص أسبوعيًا</small></th>`).join('')}</tr></thead><tbody>${rows.map((c,i)=>`${!i||c.grade!==rows[i-1].grade?`<tr class="grade-divider"><th colspan="8" scope="rowgroup">${grades[c.grade]} <span>— ${ar(classrooms.filter(x=>x.grade===c.grade).length)} شعب</span></th></tr>`:''}<tr><th scope="row"><bdi dir="ltr">${code(c)}</bdi><small>${classLabel(c)}</small></th>${subjects.map(s=>{const r=requirements.find(x=>x.classId===c.id&&x.subjectId===s.id);if(!r)return '<td><span class="empty-state">غير مقرر</span></td>';const a=assignments.get(r.id),dirty=JSON.stringify(a)!==JSON.stringify(baseline.get(r.id));return `<td>${!matches(r)?'<span class="empty-state">—</span>':`<button class="cell ${!a?.members.length?'pending-cell':''} ${dirty?'changed-cell':''}" data-edit="${r.id}" aria-label="${esc(s.name+' · '+classLabel(c))}"><span class="cell-meta">${ar(r.quota)} حصص ${r.pairs?'· مزدوجة':''}</span>${a?.members.length?`<strong>${a.members.map(m=>esc(teachers.find(t=>t.id===m.id).name)).join(' + ')}</strong><span class="cell-badge">${a.mode==='SplitQuota'?`تقسيم ${a.members.map(m=>ar(m.count)).join(' / ')}`:a.mode==='CoTeaching'?'تدريس مشترك':'معلم واحد'}</span>`:`<span class="pending-label">${icon('plus')}إسناد معلم</span>`}<span class="cell-plus">${icon('plus')}</span></button>`}</td>`;}).join('')}</tr>`).join('')}</tbody></table>${!rows.length?'<p class="empty-state">لا توجد إسنادات تطابق البحث. جرّب تغيير الفلاتر.</p>':''}</div>`;
}
function matches(r){if(pendingOnly&&assignments.get(r.id)?.members.length)return false;if(!search)return true;const c=classrooms.find(x=>x.id===r.classId);return [classLabel(c),code(c),subjects.find(s=>s.id===r.subjectId).name,...(assignments.get(r.id)?.members.map(m=>teachers.find(t=>t.id===m.id).name)||[])].some(x=>x.includes(search));}
function teacherTable(){const start=(page-1)*8;return `<div class="table-scroll"><table class="teacher-table"><thead><tr><th>المعلم</th><th>التخصص</th><th>الفصول</th><th>المسند / الحد</th><th>المتبقي</th></tr></thead><tbody>${teachers.slice(start,start+8).map(t=>{const n=load(t.id),classes=new Set(requirements.filter(r=>assignments.get(r.id)?.members.some(m=>m.id===t.id)).map(r=>r.classId));return `<tr><td><div class="teacher-identity"><span class="initial">${t.name.split(' ').map(x=>x[0]).join(' ')}</span><strong>${t.name}</strong></div></td><td>${t.specialty}</td><td>${ar(classes.size)}</td><td><bdi>${ar(n)} / ${ar(t.max)}</bdi><div class="load-track"><i style="width:${n/t.max*100}%"></i></div></td><td>${ar(t.max-n)} حصة</td></tr>`;}).join('')}</tbody></table></div><div class="pager"><span>${ar(start+1)}–${ar(Math.min(start+8,teachers.length))} من ${ar(teachers.length)} معلمًا</span><div>${[1,2,3].map(n=>`<button data-page="${n}" aria-current="${page===n?'page':'false'}">${ar(n)}</button>`).join('')}</div></div>`;}
function catalogMarkup(){return `<div class="catalog-intro"><div><h2>المرحلة المتوسطة · ٢٠٢٦–٢٠٢٧</h2><p>الصف ثم رقم الشعبة. الاسم المختصر والاسم الكامل يظهران تلقائيًا.</p></div><button class="primary" data-action="new-classes">${icon('plus')}إضافة شعب صف</button></div><div class="catalog-groups">${[1,2,3].map(g=>`<section class="grade-card"><header><h3>${grades[g]}</h3><span>${ar(classrooms.filter(c=>c.grade===g).length)} شعب</span></header>${classrooms.filter(c=>c.grade===g).map(c=>`<div class="class-row"><span class="class-number">${ar(c.section)}</span><div><strong>${classLabel(c)}</strong><small>الرمز <bdi dir="ltr">${code(c)}</bdi> · العام ٢٠٢٦–٢٠٢٧</small></div><span class="active-mark">نشط</span></div>`).join('')}<footer>تظهر هذه الفصول في الاختيارات المرتبطة بهذا العام.</footer></section>`).join('')}</div>`;}
function teacherMarkup(){return `<div class="teacher-choice-layout"><section class="surface"><header class="ledger-heading"><div class="teacher-identity"><span class="initial">أ ع</span><div><h2>أحمد عبدالله</h2><p>الرياضيات · المرحلة المتوسطة · حساب معلم تجريبي</p></div></div></header><details class="class-selector"><summary><span>اختر من فصول المدرسة</span><small id="dropdown-count">${ar(selectedClasses.size)} محددة</small>${icon('arrow')}</summary><div class="selection-menu"><div class="filters"><label class="search-field">${icon('search')}<input id="class-search" type="search" placeholder="ابحث عن صف أو شعبة" aria-label="البحث في فصول المدرسة"></label></div><div class="choices">${[1,2,3].map(g=>`<fieldset class="choice-group"><legend>${grades[g]}</legend><div class="choices-grid">${classrooms.filter(c=>c.grade===g).map(c=>`<label class="class-choice" data-label="${classLabel(c)} ${code(c)}"><input type="checkbox" data-class="${c.id}" ${selectedClasses.has(c.id)?'checked':''}><span><bdi dir="ltr">${code(c)}</bdi><small>شعبة ${ar(c.section)}</small></span></label>`).join('')}</div></fieldset>`).join('')}</div></div></details><p class="choice-note">حفظ فصولك يعتمد اختيارك مباشرة. توزيع حصص المواد ومواعيدها يظل من إسنادات التدريس والجدول المنشور.</p></section><aside class="selection-summary"><h3>الفصول التي اخترتها</h3><p><span id="selected-count">${ar(selectedClasses.size)}</span> فصول من سجل المدرسة</p><div class="selected-chips" id="selected-chips">${selectedMarkup()}</div><button class="primary" data-action="save-classes">${icon('check')}حفظ فصولي</button></aside></div>`;}
function selectedMarkup(){return [...selectedClasses].map(id=>classrooms.find(c=>c.id===id)).filter(Boolean).map(c=>`<span>${classLabel(c)}</span>`).join('')||'<small>اختر فصلًا من القائمة.</small>';}
function openAssignment(id){editing=requirements.find(r=>r.id===id);const a=assignments.get(id)||{mode:'SingleTeacher',members:[]};editMode=a.mode;editMembers=structuredClone(a.members);pickerSearch='';renderPicker();openDialog('#assignment-dialog');}
function pickerError(){if(!editMembers.length)return '';if(editMembers.length===1&&editMode!=='SingleTeacher')return 'معلم واحد يحتاج اختيار «معلم واحد».';if(editMembers.length>1&&editMode==='SingleTeacher')return 'اختر التدريس المشترك أو تقسيم الحصص.';if(editMembers.some(m=>!Number.isInteger(m.count)||m.count<0||!Number.isInteger(m.pairs)||m.pairs<0||2*m.pairs>m.count))return 'أدخل أعدادًا صحيحة. كل حصة مزدوجة تحتاج حصتين لدى المعلم نفسه.';if(editMode==='SplitQuota'&&(editMembers.reduce((n,m)=>n+m.count,0)!==editing.quota||editMembers.reduce((n,m)=>n+m.pairs,0)!==editing.pairs))return 'وزّع جميع الحصص والأزواج دون زيادة أو نقص.';if(editMembers.some(m=>load(m.id,{mode:editMode,members:editMembers})>teachers.find(t=>t.id===m.id).max))return 'هذا الإسناد يتجاوز الحد الأسبوعي لأحد المعلمين. عدّل التوزيع.';return '';}
function renderPicker(){const c=classrooms.find(c=>c.id===editing.classId),s=subjects.find(s=>s.id===editing.subjectId);
 $('#assignment-content').innerHTML=`<header class="dialog-header"><div><small>${classLabel(c)} · ${ar(editing.quota)} حصص ${editing.pairs?'· زوج واحد كامل':''}</small><h2 id="assignment-title">إسناد ${s.name}</h2></div><button data-close="assignment-dialog" aria-label="إغلاق الإسناد">${icon('close')}</button></header><div class="picker-toolbar"><label class="search-field">${icon('search')}<input id="picker-search" type="search" value="${esc(pickerSearch)}" placeholder="ابحث عن معلم أو تخصص" aria-label="البحث عن معلم"></label><p>${ar(editMembers.length)} معلمون محددون</p></div><div class="teacher-options">${teachers.filter(t=>(t.name+' '+t.specialty).includes(pickerSearch)).map(t=>`<label class="teacher-option"><input type="checkbox" data-member="${t.id}" ${editMembers.some(m=>m.id===t.id)?'checked':''}><div class="teacher-identity"><span class="initial">${t.name[0]}</span><div><strong>${t.name}</strong><small>${t.specialty}</small>${t.subjectId!==s.id?'<span class="specialization-warning">خارج التخصص · مسموح مع التنبيه</span>':''}</div></div><span class="capacity">${ar(t.max-load(t.id))} حصة متاحة<small>المسند ${ar(load(t.id))} من ${ar(t.max)}</small></span></label>`).join('')}</div><div class="selection-config"><label>نوع الإسناد<select id="assignment-mode"><option value="SingleTeacher" ${editMode==='SingleTeacher'?'selected':''}>معلم واحد</option><option value="CoTeaching" ${editMode==='CoTeaching'?'selected':''}>تدريس مشترك</option><option value="SplitQuota" ${editMode==='SplitQuota'?'selected':''}>تقسيم الحصص</option></select></label><div id="allocation-fields">${allocationMarkup()}</div><p id="picker-validation" class="validation-message" role="status"></p></div><footer class="dialog-footer"><button class="primary" data-action="confirm-assignment">تأكيد الإسناد</button><button data-close="assignment-dialog">إلغاء</button></footer>`;updateValidation();
}
function allocationMarkup(){return editMode==='SplitQuota'?editMembers.map(m=>`<div class="allocation-row"><span>${teachers.find(t=>t.id===m.id).name}</span><div class="allocation-inputs"><label>حصص<input type="number" data-count="${m.id}" value="${m.count}" min="0" max="${editing.quota}" aria-label="حصص ${teachers.find(t=>t.id===m.id).name}"></label><label>أزواج<input type="number" data-pairs="${m.id}" value="${m.pairs}" min="0" max="${editing.pairs}" aria-label="أزواج ${teachers.find(t=>t.id===m.id).name}"></label></div></div>`).join(''):'';}
function updateValidation(){const message=pickerError();$('#picker-validation').textContent=message||(editMode==='CoTeaching'?'كل معلم يتحمل النصاب الكامل. يظهر الاسمان في الجدول.':editMode==='SplitQuota'?`الموزّع ${ar(editMembers.reduce((n,m)=>n+m.count,0))} من ${ar(editing.quota)} حصص. كل زوج يبقى كاملًا لدى معلم واحد.`:editMembers.length?'النصاب محسوب مع بقية إسنادات المعلم.':'تأكيد بدون معلمين يلغي إسناد هذه الخلية.');$('#picker-validation').classList.toggle('error',!!message);$('[data-action=confirm-assignment]').disabled=!!message;}
function officialMarkup(){const extra=[];for(const r of requirements){if(r.subjectId>=5)continue;for(const m of assignments.get(r.id)?.members||[]){const t=teachers.find(t=>t.id===m.id);if(t.subjectId!==r.subjectId)extra.push(`${t.name}: ${subjects.find(s=>s.id===r.subjectId).name} / ${classLabel(classrooms.find(c=>c.id===r.classId))} / ${ar(m.count)} حصص`);}}const rows=teachers.map((t,i)=>{const owned=requirements.flatMap(r=>{const a=assignments.get(r.id),m=a?.members.find(m=>m.id===t.id);return m?[{r,a,m,c:classrooms.find(c=>c.id===r.classId)}]:[];});const spec=owned.filter(x=>x.r.subjectId===t.subjectId),other=owned.filter(x=>x.r.subjectId!==t.subjectId);const cell=list=>list.map(x=>`<bdi class="cell-code">${code(x.c)}</bdi>${x.a.mode==='SplitQuota'?`<sup> (${ar(x.m.count)}ح)</sup>`:x.a.mode==='CoTeaching'?'<sup> مشترك</sup>':''}`).join('، ');return `<tr><td>${ar(i+1)}</td><td class="teacher-name">${t.name}</td><td>${t.specialty}</td>${[1,2,3].map(g=>`<td>${cell(spec.filter(x=>x.c.grade===g))}</td>`).join('')}<td>${ar(spec.reduce((n,x)=>n+x.m.count,0))}</td>${[5,6,7].map(s=>`<td>${cell(other.filter(x=>x.r.subjectId===s))}</td>`).join('')}<td>${ar(load(t.id))}</td></tr>`;}).join('');return `<header class="official-header"><div><p>المملكة العربية السعودية</p><p>وزارة التعليم</p><p>مدرسة الفلاح التجريبية</p></div><div class="official-wordmark">وزارة التعليم<br><small>نموذج كشف الإسنادات</small></div><div><img src="brand.png" alt="مدارس الفلاح"><p>مدارس الفلاح</p></div></header><table class="paper-table"><colgroup><col style="width:3%"><col style="width:16%"><col style="width:11%"><col style="width:12%"><col style="width:12%"><col style="width:12%"><col style="width:6%"><col style="width:8%"><col style="width:7%"><col style="width:7%"><col style="width:6%"></colgroup><thead><tr><th colspan="11" class="title-cell">إسنادات المواد للمعلمين لعام ١٤٤٨ هـ – ١٤٤٩ هـ</th></tr><tr><th rowspan="2">م</th><th rowspan="2">اسم المعلم</th><th rowspan="2">تخصص المعلم</th><th colspan="3">إسنادات مواد التخصص للمعلمين</th><th rowspan="2">نصاب حصص التخصص</th><th colspan="3">إسنادات مواد غير التخصص للمعلمين</th><th rowspan="2">نصاب الحصص للمعلم</th></tr><tr><th>الصف الأول</th><th>الصف الثاني</th><th>الصف الثالث</th><th>مهارات حياتية</th><th>تفكير ناقد</th><th>النشاط</th></tr></thead><tbody>${rows}</tbody></table>${extra.length?`<section class="paper-addendum"><strong>ملحق إسنادات خارج التخصص لمواد أخرى</strong>${extra.map(x=>`<p>${esc(x)}</p>`).join('')}</section>`:''}<p class="paper-signoff">وكيل شؤون المعلمين: ____________________</p><p class="paper-footnote">عرض تجريبي: الرمز صف/شعبة. الأنصبة من الإسنادات المحفوظة في النموذج؛ المعلمون والأسماء تجريبية. لم تُنسخ أسماء أو توقيعات ورقة المدرسة.</p><div class="paper-example"><span>كشف كامل · ${ar(teachers.length)} معلمًا</span><span>${changed()?'مسودة غير محفوظة داخل النموذج':'نسخة محفوظة داخل النموذج'} · الفصل الدراسي الأول</span></div>`;}
function exportStatement(){if(changed()){toast('احفظ تعديلات النموذج أولًا قبل إخراج كشف الإسنادات.');return;}$('#official-sheet').innerHTML=officialMarkup();$('#export-scope').textContent=`كل المعلمين (${ar(teachers.length)})`;openDialog('#export-dialog');}
function generatedPreview(){const form=$('#class-form'),g=+form.elements.grade.value,from=+form.elements.from.value,to=+form.elements.to.value;$('#generated-preview').textContent=from>0&&to>=from&&to<=50?`سيُضاف ${ar(to-from+1)} فصول: ${grades[g]} · شعب ${ar(from)} إلى ${ar(to)}`:'اختر نطاق شعب صحيحًا من ١ إلى ٥٠.';}
document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;
 if(b.dataset.view){if(changed()&&!confirm('الانتقال يترك مسودة الإسنادات محفوظة في ذاكرة النموذج. هل تريد المتابعة؟'))return;view=b.dataset.view;render();}
 if(b.dataset.grade){grade=+b.dataset.grade;render();}if(b.dataset.page){page=+b.dataset.page;render();}if(b.dataset.edit)openAssignment(b.dataset.edit);if(b.dataset.close)closeDialog('#'+b.dataset.close);
 switch(b.dataset.action){case 'teachers':teacherView=true;page=1;render();break;case 'matrix':teacherView=false;render();break;case 'save':baseline=structuredClone(assignments);render();toast('تم حفظ الإسنادات داخل النموذج فقط.');break;case 'discard':if(confirm('تجاهل تعديلات الإسنادات داخل النموذج؟')){assignments.clear();for(const [k,v]of baseline)assignments.set(k,structuredClone(v));render();}break;case 'new-classes':$('#class-error').hidden=true;generatedPreview();openDialog('#class-dialog');break;case 'save-classes':toast(`تم اعتماد ${ar(selectedClasses.size)} فصول للمعلم داخل النموذج، دون انتظار موافقة.`);break;case 'confirm-assignment':if(pickerError())return;if(editMembers.length)assignments.set(editing.id,{mode:editMode,members:structuredClone(editMembers)});else assignments.delete(editing.id);closeDialog('#assignment-dialog');render();break;case 'export':exportStatement();break;case 'print':window.print();break;}
});
document.addEventListener('input',event=>{const el=event.target;
 if(el.id==='matrix-search'){const pos=el.selectionStart;search=el.value;render();$('#matrix-search').focus();$('#matrix-search').setSelectionRange(pos,pos);}
 if(el.id==='picker-search'){const pos=el.selectionStart;pickerSearch=el.value;renderPicker();$('#picker-search').focus();$('#picker-search').setSelectionRange(pos,pos);}
 if(el.id==='class-search'){$$('.class-choice').forEach(c=>c.hidden=!c.dataset.label.includes(el.value));}
 if(el.dataset.count||el.dataset.pairs){const id=+(el.dataset.count||el.dataset.pairs),m=editMembers.find(m=>m.id===id);if(el.dataset.count)m.count=+el.value;else m.pairs=+el.value;updateValidation();}
 if(el.closest('#class-form'))generatedPreview();
});
document.addEventListener('change',event=>{const el=event.target;
 if(el.id==='pending-filter'){pendingOnly=el.checked;render();}
 if(el.dataset.class){const id=+el.dataset.class;if(el.checked)selectedClasses.add(id);else selectedClasses.delete(id);$('#selected-count').textContent=ar(selectedClasses.size);$('#dropdown-count').textContent=ar(selectedClasses.size)+' \u0645\u062d\u062f\u062f\u0629';$('#selected-chips').innerHTML=selectedMarkup();}
 if(el.dataset.member){const id=+el.dataset.member;if(el.checked)editMembers.push({id,count:editing.quota,pairs:editing.pairs});else editMembers=editMembers.filter(m=>m.id!==id);if(editMembers.length<=1)editMode='SingleTeacher';renderPicker();}
 if(el.id==='assignment-mode'){editMode=el.value;if(editMode!=='SplitQuota')editMembers.forEach(m=>{m.count=editing.quota;m.pairs=editing.pairs;});$('#allocation-fields').innerHTML=allocationMarkup();updateValidation();}
});
$('#class-form').addEventListener('submit',event=>{event.preventDefault();const form=event.target,g=+form.elements.grade.value,from=+form.elements.from.value,to=+form.elements.to.value,error=$('#class-error');if(!Number.isInteger(from)||!Number.isInteger(to)||from<1||to<from||to>50){error.textContent='أدخل نطاقًا صحيحًا بين ١ و٥٠.';error.hidden=false;return;}if(classrooms.some(c=>c.grade===g&&c.section>=from&&c.section<=to)){error.textContent='إحدى الشعب موجودة بالفعل. غيّر النطاق؛ لم تُضف أي فصول.';error.hidden=false;return;}let next=Math.max(...classrooms.map(c=>c.id))+1;for(let section=from;section<=to;section++)classrooms.push({id:next++,grade:g,section});classrooms.sort((a,b)=>a.grade-b.grade||a.section-b.section);closeDialog('#class-dialog');render();toast('أُضيفت الفصول. تظهر الآن في قائمة اختيار المعلم؛ متطلبات المواد تُعدّ بشكل مستقل.');});
$$('dialog').forEach(d=>d.addEventListener('cancel',event=>{event.preventDefault();closeDialog('#'+d.id);}));
window.addEventListener('beforeunload',event=>{if(changed()){event.preventDefault();event.returnValue='';}});
render();
